apps.preload:
// Runs inside open.spotify.com.
// 1. Spotify Connect lists this player as "Web Player (Chrome)"; this renames it "Spotify Mini" (on your
//    phone, speakers and the Devices list) by changing the name in the device-registration requests.
// 2. Player mode: the panel shrinks to a small player (artwork, song, progress, controls). Turn it on
//    with Spotify's own "Open Miniplayer" button, or right-click the taskbar button → Player mode.
//    Every control just presses Spotify's real button, so it behaves exactly like the full player.
const { contextBridge, webFrame, ipcRenderer } = require('electron');

function rename(NAME) {
  const fix = (body) => {
    if (typeof body !== 'string' || body.indexOf('Web Player') < 0) return body;
    return body.replace(/("name"\s*:\s*")Web Player[^"]*(")/g, `$1${NAME}$2`);
  };
  const fetch0 = window.fetch;
  window.fetch = function (input, init) {
    if (init && typeof init.body === 'string') init = Object.assign({}, init, { body: fix(init.body) });
    return fetch0.call(this, input, init);
  };
  const send0 = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.send = function (body) { return send0.call(this, fix(body)); };
}

try {
  // Runs straight away in the page's own world, before Spotify's scripts.
  contextBridge.executeInMainWorld({ func: rename, args: ['Spotify Mini'] });
} catch {
  webFrame.executeJavaScript(`(${rename})('Spotify Mini')`);
}

// ---------------- player mode ----------------
const q = (id) => document.querySelector(`[data-testid="${id}"]`);
const press = (id) => { const b = q(id); if (b) b.click(); };

const secs = (t) => { const p = String(t || '').trim().split(':').map(Number); return p.some(isNaN) ? NaN : p.reduce((a, n) => a * 60 + n, 0); };

function readPlayer() {
  const bar = q('control-button-playpause');
  if (!bar) return null; // logged out, or the page is still loading
  const md = navigator.mediaSession && navigator.mediaSession.metadata;
  const w = q('now-playing-widget');
  let title = md && md.title, artist = md && md.artist, art = '';
  if (md && md.artwork && md.artwork.length) {
    art = [...md.artwork].sort((a, b) => (parseInt(b.sizes, 10) || 0) - (parseInt(a.sizes, 10) || 0))[0].src;
  }
  if (!title && w) {
    title = (w.querySelector('[data-testid="context-item-link"]') || {}).textContent || '';
    artist = [...w.querySelectorAll('[data-testid="context-item-info-artist"]')].map((a) => a.textContent).join(', ');
  }
  if (!art && w) { const img = w.querySelector('img'); if (img) art = img.src.replace('00004851', '0000b273'); }
  const ps = navigator.mediaSession && navigator.mediaSession.playbackState;
  const playing = ps === 'playing' || (ps !== 'paused' && /pause/i.test(bar.getAttribute('aria-label') || ''));
  const pos = (q('playback-position') || {}).textContent || '';
  const dur = (q('playback-duration') || {}).textContent || '';
  const range = rangeInput();
  let frac = range ? (Number(range.value) - Number(range.min || 0)) / ((Number(range.max) || 1) - Number(range.min || 0)) : secs(pos) / secs(dur);
  if (!isFinite(frac)) frac = 0;
  const shuffle = (q('control-button-shuffle') || { getAttribute: () => null }).getAttribute('aria-checked') === 'true';
  const repeat = (q('control-button-repeat') || { getAttribute: () => null }).getAttribute('aria-checked') || 'false';
  return { title: title || '', artist: artist || '', art, playing, pos, dur, frac: Math.min(1, Math.max(0, frac)), shuffle, repeat };
}

function rangeInput() { const p = q('playback-progressbar'); return p && p.querySelector('input[type="range"]'); }

function seek(frac) {
  const r = rangeInput();
  if (!r) return;
  const min = Number(r.min || 0), max = Number(r.max) || 1;
  Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(r, String(Math.round(min + frac * (max - min))));
  r.dispatchEvent(new Event('input', { bubbles: true }));
  r.dispatchEvent(new Event('change', { bubbles: true }));
}

const ICON = {
  play: '<path fill="currentColor" d="M8 5.14v13.72a1 1 0 0 0 1.52.85l10.6-6.86a1 1 0 0 0 0-1.7L9.52 4.29A1 1 0 0 0 8 5.14z"/>',
  pause: '<path fill="currentColor" d="M7 4.5h3.2a.8.8 0 0 1 .8.8v13.4a.8.8 0 0 1-.8.8H7a.8.8 0 0 1-.8-.8V5.3a.8.8 0 0 1 .8-.8zm6.8 0H17a.8.8 0 0 1 .8.8v13.4a.8.8 0 0 1-.8.8h-3.2a.8.8 0 0 1-.8-.8V5.3a.8.8 0 0 1 .8-.8z"/>',
  next: '<path fill="currentColor" d="M5 5.6v12.8a.8.8 0 0 0 1.23.67L15.6 12.7a.8.8 0 0 0 0-1.36L6.23 4.93A.8.8 0 0 0 5 5.6zM17 5h2v14h-2z"/>',
  prev: '<path fill="currentColor" d="M19 5.6v12.8a.8.8 0 0 1-1.23.67L8.4 12.7a.8.8 0 0 1 0-1.36l9.37-6.41A.8.8 0 0 1 19 5.6zM5 5h2v14H5z"/>',
  shuffle: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 3h5v5M4 20 21 3M21 16v5h-5M15 15l6 6M4 4l5 5"/></g>',
  repeat: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m17 2 4 4-4 4M3 11v-1a4 4 0 0 1 4-4h14M7 22l-4-4 4-4M21 13v1a4 4 0 0 1-4 4H3"/></g>',
  expand: '<g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7"/></g>',
};
const svg = (name) => `<svg viewBox="0 0 24 24" width="100%" height="100%" aria-hidden="true">${ICON[name]}</svg>`;

const CSS = `
:host { all: initial; }
.wrap { position: fixed; inset: 0; z-index: 2147483646; background: #121212; color: #fff; overflow: hidden;
  font: 14px/1.4 "SpotifyMixUI", "Segoe UI", system-ui, sans-serif; display: flex; flex-direction: column;
  user-select: none; -webkit-user-select: none; }
.bg { position: absolute; inset: -40px; background-size: cover; background-position: center; filter: blur(40px) saturate(1.3);
  opacity: .45; transition: background-image .4s; }
.shade { position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(18,18,18,.15), rgba(18,18,18,.85) 70%); }
.body { position: relative; flex: 1; display: flex; flex-direction: column; padding: 14px 16px 12px; min-height: 0; gap: 10px; }
[hidden] { display: none !important; }
.art { flex: 1; min-height: 60px; overflow: hidden; display: flex; align-items: center; justify-content: center; }
.art img { width: var(--side, 120px); height: var(--side, 120px); object-fit: cover; border-radius: 8px;
  box-shadow: 0 8px 30px rgba(0,0,0,.5); }
.art .none { width: 120px; height: 120px; border-radius: 8px; background: #282828; display: grid; place-items: center; color: #b3b3b3; }
.row { display: flex; align-items: center; gap: 8px; }
.text { flex: 1; min-width: 0; }
.title { font-weight: 700; font-size: 17px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.artist { color: #b3b3b3; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bar { position: relative; height: 16px; cursor: pointer; display: flex; align-items: center; }
.track { width: 100%; height: 4px; border-radius: 2px; background: rgba(255,255,255,.25); overflow: hidden; }
.fill { height: 100%; background: #fff; border-radius: 2px; }
.bar:hover .fill { background: #1ed760; }
.times { display: flex; justify-content: space-between; color: #b3b3b3; font-size: 11px; font-variant-numeric: tabular-nums; margin-top: -4px; }
.controls { display: flex; align-items: center; justify-content: center; gap: 14px; }
button { all: unset; box-sizing: border-box; cursor: pointer; color: #b3b3b3; width: 32px; height: 32px; padding: 6px;
  border-radius: 50%; display: grid; place-items: center; transition: color .15s, transform .1s, background .15s; }
button:hover { color: #fff; }
button:active { transform: scale(.94); }
button:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
button.on { color: #1ed760; }
button.main { width: 48px; height: 48px; padding: 13px; background: #fff; color: #000; }
button.main:hover { transform: scale(1.05); color: #000; }
button.small { width: 30px; height: 30px; padding: 7px; }
.repeat-one { position: relative; }
.repeat-one::after { content: "1"; position: absolute; inset: 0; display: grid; place-items: center; font: 800 9px system-ui, sans-serif; }
.empty { position: relative; flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px;
  color: #b3b3b3; text-align: center; padding: 20px; }
.empty button { all: unset; cursor: pointer; background: #1ed760; color: #000; font-weight: 700; padding: 8px 18px; border-radius: 999px; }
`;

let compact = false, root = null, els = null, timer = null, panelHidden = false, last = '';

function build() {
  const host = document.createElement('div');
  host.id = 'mini-player-root';
  const sh = host.attachShadow({ mode: 'closed' });
  sh.innerHTML = `<style>${CSS}</style>
  <div class="wrap">
    <div class="bg"></div><div class="shade"></div>
    <div class="body" data-k="body">
      <div class="art" data-k="art"></div>
      <div class="row">
        <div class="text"><div class="title" data-k="title"></div><div class="artist" data-k="artist"></div></div>
        <button class="small" data-k="full" title="Back to the full player" aria-label="Back to the full player">${svg('expand')}</button>
      </div>
      <div>
        <div class="bar" data-k="bar" role="slider" aria-label="Seek"><div class="track"><div class="fill" data-k="fill"></div></div></div>
        <div class="times"><span data-k="pos"></span><span data-k="dur"></span></div>
      </div>
      <div class="controls">
        <button data-k="shuffle" aria-label="Shuffle">${svg('shuffle')}</button>
        <button data-k="prev" aria-label="Previous">${svg('prev')}</button>
        <button class="main" data-k="play" aria-label="Play">${svg('play')}</button>
        <button data-k="next" aria-label="Next">${svg('next')}</button>
        <button data-k="repeat" aria-label="Repeat">${svg('repeat')}</button>
      </div>
    </div>
    <div class="empty" data-k="empty" hidden><div>Log in to Spotify to use player mode.</div><button data-k="login">Open full player</button></div>
  </div>`;
  els = {};
  sh.querySelectorAll('[data-k]').forEach((e) => { els[e.dataset.k] = e; });
  els.bg = sh.querySelector('.bg');
  // Artwork: the biggest square that fits the space left over.
  new ResizeObserver(([e]) => {
    const side = Math.floor(Math.min(e.contentRect.width, e.contentRect.height));
    els.art.style.setProperty('--side', `${Math.max(side, 40)}px`);
  }).observe(els.art);
  els.play.onclick = () => { press('control-button-playpause'); setTimeout(update, 150); };
  els.next.onclick = () => { press('control-button-skip-forward'); setTimeout(update, 300); };
  els.prev.onclick = () => { press('control-button-skip-back'); setTimeout(update, 300); };
  els.shuffle.onclick = () => { press('control-button-shuffle'); setTimeout(update, 150); };
  els.repeat.onclick = () => { press('control-button-repeat'); setTimeout(update, 150); };
  els.full.onclick = () => setCompact(false);
  els.login.onclick = () => setCompact(false);
  els.bar.onclick = (e) => { const r = els.bar.getBoundingClientRect(); seek((e.clientX - r.left) / r.width); setTimeout(update, 200); };
  return host;
}

function update() {
  if (!compact || !els) return;
  const p = readPlayer();
  els.body.hidden = !p; els.empty.hidden = !!p;
  if (!p) return;
  els.title.textContent = p.title || 'Nothing playing';
  els.artist.textContent = p.artist;
  if (p.art !== last) {
    last = p.art;
    els.art.innerHTML = p.art ? `<img alt="">` : `<div class="none">♪</div>`;
    if (p.art) els.art.firstChild.src = p.art;
    els.bg.style.backgroundImage = p.art ? `url("${p.art.replace(/"/g, '%22')}")` : '';
  }
  els.fill.style.width = `${(p.frac * 100).toFixed(2)}%`;
  els.pos.textContent = p.pos; els.dur.textContent = p.dur;
  els.play.innerHTML = svg(p.playing ? 'pause' : 'play');
  els.play.setAttribute('aria-label', p.playing ? 'Pause' : 'Play');
  els.shuffle.classList.toggle('on', p.shuffle);
  els.repeat.classList.toggle('on', p.repeat !== 'false');
  els.repeat.classList.toggle('repeat-one', p.repeat === 'mixed');
}

function tick() {
  clearInterval(timer); timer = null;
  if (compact && !panelHidden) { update(); timer = setInterval(update, 500); }
}

function show(on) {
  compact = on;
  if (on && !root) root = build();
  if (root) {
    if (on && !root.isConnected) document.documentElement.appendChild(root);
    if (!on && root.isConnected) root.remove();
  }
  tick();
}

function setCompact(on) {
  show(on);
  ipcRenderer.send('panel-set-mode', on ? 'compact' : 'full');
}

// Spotify's own "Open Miniplayer" button (its picture-in-picture window doesn't work in the panel) → player mode.
document.addEventListener('click', (e) => {
  if (e.target && e.target.closest && e.target.closest('[data-testid="pip-toggle-button"]')) {
    e.preventDefault(); e.stopImmediatePropagation(); setCompact(true);
  }
}, true);
// The taskbar button's right-click menu → "Player mode (on / off)".
window.addEventListener('mini-player-mode', () => setCompact(!compact));
window.addEventListener('mini-panel', (e) => { panelHidden = e.detail === 'hidden'; tick(); });

ipcRenderer.invoke('panel-mode').then((m) => {
  const on = m === 'compact';
  if (document.documentElement) show(on);
  else document.addEventListener('DOMContentLoaded', () => show(on), { once: true });
}).catch(() => {});

ipcRenderer.send('view-log', 'spotify helper ready');

// Runs inside instagram.com. Makes Reels nice in a small panel:
//   ↓ / ↑ (also J / K, PageDown / PageUp)  next / previous reel
//   Space                                   pause / play
//   M                                       mute / unmute (remembered)
// Reels play with sound through the PC speakers (Instagram starts them muted), pause when the
// panel is hidden and carry on when it's shown again. Keys are ignored while typing (comments, DMs).
const { ipcRenderer } = require('electron');
const log = (msg) => ipcRenderer.send('view-log', msg);

const MUTE_KEY = 'miniReelsMuted';
const userMuted = () => { try { return localStorage.getItem(MUTE_KEY) === '1'; } catch { return false; } };
const setUserMuted = (v) => { try { localStorage.setItem(MUTE_KEY, v ? '1' : '0'); } catch {} };

const typing = (el) => !!el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
const shown = (v) => { const r = v.getBoundingClientRect(); return r.width > 40 && r.height > 40; };

// The reel on screen: the visible video nearest the middle of the panel.
function videos() { return [...document.querySelectorAll('video')].filter(shown); }
function current() {
  const mid = window.innerHeight / 2;
  let best = null, dist = Infinity;
  for (const v of videos()) {
    const r = v.getBoundingClientRect();
    const d = Math.abs(r.top + r.height / 2 - mid);
    if (d < dist) { dist = d; best = v; }
  }
  return best;
}
function scroller(el) {
  for (let p = el && el.parentElement; p; p = p.parentElement) {
    const s = getComputedStyle(p);
    if (/(auto|scroll)/.test(s.overflowY) && p.scrollHeight > p.clientHeight + 10) return p;
  }
  return document.scrollingElement;
}

function go(dir) {
  const cur = current();
  if (!cur) { window.scrollBy({ top: dir * window.innerHeight, behavior: 'smooth' }); return; }
  const all = videos().sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
  const next = all[all.indexOf(cur) + dir];
  if (next) next.scrollIntoView({ behavior: 'smooth', block: 'center' });
  else { const s = scroller(cur); s.scrollBy({ top: dir * s.clientHeight, behavior: 'smooth' }); } // next one not loaded yet
}

function sound(v) {
  if (!v) return;
  v.muted = userMuted();
  if (!v.muted) v.volume = 1;
}

function toast(text) {
  let t = document.getElementById('mini-reels-toast');
  if (!t) {
    t = document.createElement('div');
    t.id = 'mini-reels-toast';
    t.style.cssText = 'position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:2147483647;pointer-events:none;'
      + 'background:rgba(0,0,0,.7);color:#fff;font:600 15px system-ui,sans-serif;padding:10px 16px;border-radius:999px;transition:opacity .25s;';
    document.documentElement.appendChild(t);
  }
  t.textContent = text; t.style.opacity = '1';
  clearTimeout(toast.timer); toast.timer = setTimeout(() => { t.style.opacity = '0'; }, 700);
}

window.addEventListener('keydown', (e) => {
  if (e.ctrlKey || e.altKey || e.metaKey || typing(document.activeElement)) return;
  if (!/^\/reels?\//.test(location.pathname) && !/^(m|M)$/.test(e.key)) return; // arrows only steer Reels
  const k = e.key;
  let handled = true;
  if (k === 'ArrowDown' || k === 'PageDown' || k === 'j' || k === 'J') go(1);
  else if (k === 'ArrowUp' || k === 'PageUp' || k === 'k' || k === 'K') go(-1);
  else if (k === ' ') { const v = current(); if (v) { if (v.paused) { sound(v); v.play().catch(() => {}); toast('▶'); } else { v.pause(); toast('❚❚'); } } }
  else if (k === 'm' || k === 'M') { const m = !userMuted(); setUserMuted(m); document.querySelectorAll('video').forEach((v) => { v.muted = m; }); toast(m ? 'Muted' : 'Sound on'); }
  else handled = false;
  if (handled) { e.preventDefault(); e.stopImmediatePropagation(); }
}, true);

// Sound on: every reel that starts playing gets the speakers (unless you've pressed M).
document.addEventListener('play', (e) => { if (e.target instanceof HTMLVideoElement) sound(e.target); }, true);

// Only one reel plays at a time, and nothing plays while the panel is hidden.
document.addEventListener('playing', (e) => {
  if (!(e.target instanceof HTMLVideoElement)) return;
  if (panelHidden || document.hidden) { e.target.pause(); return; }
  document.querySelectorAll('video').forEach((v) => { if (v !== e.target && !v.paused) v.pause(); });
}, true);

// The hub says when the panel hides or shows (Mini Apps 1.4.4+): pause, then carry on where you were.
// Panels start hidden (the hub loads them in the background); focus means it's on screen.
let pausedByHide = null, panelHidden = !document.hasFocus();
window.addEventListener('focus', () => { panelHidden = false; });
window.addEventListener('mini-panel', (e) => {
  panelHidden = e.detail === 'hidden';
  if (panelHidden) {
    const v = [...document.querySelectorAll('video')].find((x) => !x.paused);
    if (v) { v.pause(); pausedByHide = v; }
  } else if (pausedByHide && pausedByHide.isConnected) {
    sound(pausedByHide); pausedByHide.play().catch(() => {});
    pausedByHide = null;
  }
});

// Stories: in a narrow panel the story tray clips the top of the coloured rings. Find each ring (or
// story button) whose top is hidden by a clipping box above it, and give that box just enough room.
const clips = (el) => { const s = getComputedStyle(el); return s.overflowX !== 'visible' || s.overflowY !== 'visible'; };
function storyBits() {
  const out = new Set();
  document.querySelectorAll('canvas').forEach((c) => {
    const r = c.getBoundingClientRect();
    if (r.width >= 40 && r.width <= 140 && Math.abs(r.width - r.height) < 6) out.add(c);
  });
  document.querySelectorAll('[aria-label*="story" i]').forEach((e) => { if (e.getBoundingClientRect().height < 160) out.add(e); });
  return out;
}
function unclipStories() {
  for (const bit of storyBits()) {
    const top = bit.getBoundingClientRect().top;
    let el = bit.parentElement;
    for (let i = 0; el && el !== document.body && i < 14; i++, el = el.parentElement) {
      if (!clips(el)) continue;
      const r = el.getBoundingClientRect();
      if (r.height > 260) break; // that's the page, not the tray
      const need = Math.ceil(r.top - top);
      if (need <= 0 || need > 24) continue;
      const s = getComputedStyle(el);
      el.style.setProperty('padding-top', `${(parseFloat(s.paddingTop) || 0) + need + 2}px`, 'important');
      if (el.scrollHeight > el.clientHeight + 1) { // fixed height: grow it too, so the names underneath still fit
        el.style.setProperty('height', `${r.height + need + 2}px`, 'important');
        el.style.setProperty('min-height', `${r.height + need + 2}px`, 'important');
      }
      log(`stories: made ${need + 2}px room above the tray`);
    }
  }
}
let unclipTimer = null;
const unclipSoon = () => { if (!unclipTimer) unclipTimer = setTimeout(() => { unclipTimer = null; unclipStories(); }, 300); };
new MutationObserver(unclipSoon).observe(document, { childList: true, subtree: true });
window.addEventListener('resize', unclipSoon);

log('instagram helper ready');

// Runs inside the doorbell's web page. The Reolink web UI forgets its login whenever the page
// reloads or the session times out, so this remembers the login you type once and fills it
// in again automatically. The password goes straight to the main process, which stores it
// encrypted with Windows DPAPI (src/main.js) - only after the doorbell accepted it.
const { ipcRenderer } = require('electron');

const visible = (el) => !!el && !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length);
const log = (msg) => ipcRenderer.send('view-log', msg);

function loginForm() {
  const pass = [...document.querySelectorAll('input[type=password]')].find(visible);
  if (!pass) return null;
  const root = pass.closest('.login-form, form') || document;
  const user = [...root.querySelectorAll('input[type=text], input:not([type])')].find(visible);
  const button = [...root.querySelectorAll('button, input[type=submit], input[type=button]')]
    .find((b) => visible(b) && /log\s*in|sign\s*in/i.test(b.innerText || b.value || ''));
  // Only the real login screen (not e.g. a "change password" page in settings).
  if (!button || !(pass.closest('.login-form') || /log\s*in/i.test(button.innerText || button.value))) return null;
  return { pass, user, button };
}

// Set a value the way typing would, so the page's framework (Vue) notices it.
function fill(input, value) {
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
  setter.call(input, value);
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
}

// Remember what you type when you press Login / Enter.
function captureTyped() {
  const f = loginForm();
  if (f && f.pass.value) ipcRenderer.send('login-typed', { user: (f.user && f.user.value) || 'admin', pass: f.pass.value });
}
document.addEventListener('click', (e) => {
  const f = loginForm();
  if (f && f.button.contains(e.target)) captureTyped();
}, true);
document.addEventListener('keydown', (e) => { if (e.key === 'Enter') captureTyped(); }, true);

let onLogin = false;
let attempts = 0;
let lastAttempt = 0;

async function tick() {
  const f = loginForm();
  if (!f) {
    if (onLogin) { log('logged in'); ipcRenderer.send('login-succeeded'); }
    onLogin = false;
    return;
  }
  if (!onLogin) log('login screen shown');
  onLogin = true;

  if (Date.now() - lastAttempt < 12000) return;           // give the last attempt time to work
  if (document.activeElement === f.pass && f.pass.value) return; // you're typing; leave it alone
  if (attempts >= 2) {                                    // saved login no longer works (password changed?)
    if (attempts === 2) { log('saved login did not work; waiting for you to log in'); ipcRenderer.send('login-rejected'); attempts++; }
    return;
  }
  const saved = await ipcRenderer.invoke('login-get');
  if (!saved || !saved.pass) return;                      // nothing saved yet: you log in once by hand
  attempts++;
  lastAttempt = Date.now();
  log(`filling in saved login (attempt ${attempts})`);
  if (f.user) fill(f.user, saved.user || 'admin');
  fill(f.pass, saved.pass);
  setTimeout(() => { const g = loginForm(); if (g) g.button.click(); }, 300);
}

// ---------- peek mode: show only the live picture, nothing else ----------
// The Reolink page draws the stream into a <video> or <canvas>; we pick the biggest one,
// hide everything else and stretch it over the whole panel. Toggle with
// document.documentElement.classList.toggle('peek') (right-click menu "Show Reolink controls").
const PEEK_CSS = `
  html.peek, html.peek body { background: #000 !important; overflow: hidden !important; }
  html.peek body * { visibility: hidden !important; }
  html.peek [data-peek], html.peek [data-peek] * { visibility: visible !important; }
  html.peek [data-peek] {
    position: fixed !important; inset: 0 !important; left: 0 !important; top: 0 !important;
    width: 100vw !important; height: 100vh !important; max-width: none !important; max-height: none !important;
    margin: 0 !important; transform: none !important; object-fit: contain !important;
    background: #000 !important; z-index: 2147483647 !important;
  }`;
let peekEl = null;
function peek() {
  if (!document.getElementById('mini-peek-css')) {
    const style = document.createElement('style');
    style.id = 'mini-peek-css';
    style.textContent = PEEK_CSS;
    (document.head || document.documentElement).appendChild(style);
    document.documentElement.classList.add('peek');
  }
  if (loginForm()) { document.documentElement.classList.remove('peek'); return; } // never hide the login
  if (!document.documentElement.dataset.peekOff) document.documentElement.classList.add('peek');
  if (peekEl && peekEl.isConnected && peekEl.hasAttribute('data-peek')) return;
  // Measure with peek styling off so we see the page's own layout.
  const was = document.documentElement.classList.contains('peek');
  document.documentElement.classList.remove('peek');
  const best = [...document.querySelectorAll('video, canvas')]
    .map((el) => ({ el, area: el.getBoundingClientRect().width * el.getBoundingClientRect().height }))
    .filter((c) => c.area > 40000)
    .sort((a, b) => b.area - a.area)[0];
  if (was) document.documentElement.classList.add('peek');
  if (!best) return;
  document.querySelectorAll('[data-peek]').forEach((el) => el.removeAttribute('data-peek'));
  best.el.setAttribute('data-peek', '');
  peekEl = best.el;
  log(`peek: showing ${best.el.tagName.toLowerCase()} only`);
}

window.addEventListener('DOMContentLoaded', () => setInterval(() => {
  tick().catch(() => {});
  try { peek(); } catch {}
}, 1000));
